    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint256 beforeBalance = address(c).balance;
        uint256 beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint256 beforeSelfBalance = address(this).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint256 afterBalance = address(c).balance;
        uint256 afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint256 afterSelfBalance = address(this).balance;

        assert(afterBalance <= beforeBalance);
    }
}

