contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBalance = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint256 beforeSelfBalance = address(this).balance;
        try c.withdraw(amount) {} catch { return; }
        uint256 afterBalance = address(c).balance;
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint256 afterSelfBalance = address(this).balance;
        assertTrue(afterBalance <= beforeBalance);
